;
var DemandConnect3 = {
	campaignHistory: null,
	campaigns: {}, //Holds the URL parameter names to watch for
	DATA:{},
	engageTime:0,
	errorSent:null,
	isReturnFromSubmit: false,
	orgId:null,
	referringDomain: null,
	referringUrl: null,
	settings: {
		form: (document.getElementById('DemandConnectForm')) ? document.getElementById('DemandConnectForm') : null, //The form
		serverURL: 'https://ods.evariant.com/hcx/index.php/DemandConnect3/getClientInfo/callback/DemandConnect3.dataReady', //The DemandConnect3 server side
		errorURL: 'https://ods.evariant.com/hcx/index.php/DemandConnect3/logError/callback/DemandConnect3.errorReady', //The DemandConnect3 server side
		masterCookieName: 'EVXSiteVisitMaster', //DemandConnect3 Cookie
		sessionCookieName: 'EVXSiteVisitSession', //DemandConnect3 Cookie
		dcCookieName: 'CampaignHistory', //Cookie
		masterCookieDays: (365*10), //DemandConnect3 Cookie Length
		sessionCookieDays: 1, //DemandConnect3 Cookie Length
		keywordParams: ['q', 'p', 'query'], //Holds the params used by search engines to send keywords
		timestampFormat: 'Y-m-d H:i:s O' //Holds the format for the timestamp
	},

	//Current campaign
	campaign: {
		value:			null,
		key:			null,
		field:			null,
		keyword:		null,
		referrer:		null,
		referrerDomain:	null
	},

	//Holds the 2 types of special campaigns
	specialCampaigns: {
		direct:		null,
		referral:	null
	},

	//Simulated Constructor
	__construct: function() {


		this.referringUrl = document.referrer;

		this.referringDomain = this.referringUrl.split('/')[2];

		if (this.getQueryParam('dcFormReturn') == 1) {
			this.isReturnFromSubmit = true;
			this.clearCampaigns();
		}
	},

	refreshWithOverrides: function(name, value){
		if(name && name != false){
			if ( window.location.href.indexOf(name) < 0 ) {
				if ( window.location.href.indexOf('?') > 0 ) {
					window.location.href += '&' + name + '=' + value;
				} else {
					window.location.href += '?' +  name + '=' + value;
				}
			}
		}
	},

	/**
	 * Retrieves a cookie value
	 * @param string The cookie name to retrieve
	 * @return string The cookie
	 */
	getCookie: function(name) {
		var nameEQ = name + "=";
		var ca = document.cookie.split(';');
		for (var i=0; i < ca.length; i++) {
			var c = ca[i];
			while (c.charAt(0) == ' ') {
				c = c.substring(1, c.length);
			}
			if (c.indexOf(nameEQ) == 0) {
				return c.substring(nameEQ.length, c.length);
			}
		}
		return null;
	},

	/**
	 * Sets a cookie value
	 * @param string The name of the cookie
	 * @param string The cookie value
	 * @param int The number of days until the cookie expires
	 */
	setCookie: function(name, value, days) {
		var expires;
		if (days) {
			var date = new Date();
			date.setTime(date.getTime() + (days * 24 * 60 * 60 * 1000));
			expires = "; expires=" + date.toGMTString();
		} else {
			expires = "";
		}
		document.cookie = name + "=" + value + expires + "; path=/";
	},

	/**
	 * Returns the domain of a URL (note: strips the 'www')
	 * @param string The URL to use
	 * @param boolean OPTIONAL If true, return the registered domain only (no subdomains)
	 * @return string The domain
	 */
	getDomain: function(url, isRegistered) {
		if (!url) {
			return '';
		}
		var domain = url.split('\/')[2].split('?')[0];
		if (isRegistered) {
			domain = domain.split('.').reverse();
			domain = domain[1] + '.' + domain[0];
		} else {
			domain = domain.replace(/^www\./, '');
		}
		return domain;
	},

	/**
	 * Returns the hostname of a URL (note: strips the subdomains and extension)
	 * @param string The URL to use
	 * @return object The hostname (registered domain minus the extension)
	 */
	getHost: function(url) {
		return this.getDomain(url, true).split('.')[0].toLowerCase();
	},

	/**
	 * Returns a query string parameter's value
	 * @param string The key
	 * @param string OPTIONAL The URL to retrieve the param from. Defaults to the current URL
	 * @return string The key's value or empty string
	 */
	getQueryParam: function(key, url) {
		if (!url) {
			url = window.location.href;
		}
		key = key.replace(/[\[]/, "\\\[").replace(/[\]]/, "\\\]");
		var regexS = "[\\?&]" + key + "=([^&#]*)";
		var regex = new RegExp(regexS);
		var results = regex.exec(url);
		return (
			!results
			? ''
			: decodeURIComponent((results[1]/* + ''*/).replace(/\+/g, '%20'))
		);
	},

	/**
	 * Determines the keyword
	 * @return string The keyword
	 */
	getKeyword: function() {
		var keyword;
		var params = this.settings.keywordParams;
		for (var i=0; i < params.length; i++) {
			if (keyword = this.getQueryParam(params[i], this.referringUrl)) {
				return keyword;
			}
		}
		return '';
	},

	/**
	 * Retrieves a timestamp
	 * @param string The format of the string. This is similiar to PHP dates
	 * @return string The timestamp in desired format
	 */
	getTimestamp: function(format) {
		return (new Date()).format(format);
	},

	/**
	 * Determines if the campaign is listed in the campaign history
	 * @param string The campaign id
	 * @return boolean True if the campaign is in the history
	 */
	hasCampaign: function(campaignId) {
		var ch = this.campaignHistory;
		for (var i=0; i < ch.length; i++) {
			if (ch[i].value == campaignId) {
				return true;
			}
		}
		return false;
	},

	/**
	 * Clears the campaign history
	 */
	clearCampaigns: function() {
		this.setCookie('CampaignHistory', '');
		this.campaignHistory = new Array();
	},

	/**
	 * Retrieves and sets the campaign history
	 * @return array The campaign history
	 */
	getCampaignHistory: function() {
		if (!this.campaignHistory) {
			var ch = this.getCookie('CampaignHistory');
			try {
				this.campaignHistory = (ch ? DCJSON.parse(ch) : new Array());
			} catch (e) {
				//alert(ch);
				this.campaignHistory = new Array();
			}
		}
		return this.campaignHistory;
	},

	getCampaign: function(campaignId) {
		var ch = this.campaignHistory;
		for (var i=0; i < ch.length; i++) {
			if (ch[i].value == campaignId) {
				return ch[i];
			}
		}
		return false;
	},

	/**
	 * Adds a campaign to the user's campaign history
	 * @param object The campaign
	 */
	addCampaign: function(campaign) {
		if (!campaign || !campaign.value) {
			return false;
		}

		this.campaign = campaign;
		this.campaign.timestamp = this.getTimestamp(this.settings.timestampFormat);
		this.campaign.referrer = this.referringUrl.replace(';', '');
		this.campaign.referrerDomain = this.getDomain(this.referringUrl, true);

		if (this.campaignHistory.length >= 4) {
			this.campaignHistory[3] = campaign;
		} else {
			this.campaignHistory.push(campaign);
		}
		this.setCookie('CampaignHistory', DCJSON.stringify(this.campaignHistory));
	},

	addToForm: function(c, pageHistory){
		//If DC is also included
		this.removeDemandconnectInputs();

		var dcForm = document.getElementsByName('DemandConnect.Form');
		if (dcForm.length > 0) {
			for(var i = 0; i < dcForm.length; i++) {

				if(HCMACID){ //Always use HCMACID
					this.addCampaignsToForm(dcForm[i].parentNode, c);
					//if(this.debug){
						//console.log(c);
						//console.log("added from hcmacid");
					//}

				}else{
					if(pageHistory.length > 1){ //there is a history
						for (var x=0; x < pageHistory.length; x++) {
							if(pageHistory[x].HCMACID != 'undefined' && pageHistory[x].HCMACID != null &&  pageHistory[x].HCMACID != "null"){
								this.addCampaignsToForm(dcForm[i].parentNode, pageHistory[x]);
								added = true;
								//if(this.debug){
									//console.log(pageHistory[x]);
									//console.log('Added from History');
								//}
								break;
							}
						}
					}

					//Not added from history and no hcmacid
					if(added == false){
						if(!c.field){
							c.value = this.specialCampaigns.direct;
							c.field = 'direct';
						}
						//if(this.debug){
							//console.log(c);
							//console.log('Added from ' + c.field);
						//}
						this.addCampaignsToForm(dcForm[i].parentNode, c);
					}

				}

			}
		}
	},

	/**
	 * Adds the campaign history information to a form by adding
	 * hidden inputs to it
	 * @param string|object The form id or the object to add the history to
	 * @param string OPTIONAL The email address form field id
	 */
	addCampaignsToForm: function(formId, campaign) {
		var form = (
			typeof formId == 'object'
			? formId
			: document.getElementById(formId)
		);


		if(typeof campaign == 'object'){
			//Merge history and campaign
			var ch = this.campaignHistory;
			var c = [];
			//campaign.status = (document.getElementsByName('HC4__MarketingAssetCampaignMember__c.HC4__Status__c').value ? document.getElementsByName('HC4__MarketingAssetCampaignMember__c.HC4__Status__c').value : 'Responded');

			c.push(campaign);

			if(ch.length){
				for (var i=0; i < ch.length; i++) {
					if (ch[i].value != campaign.value) {
						c.push(ch[i]);
					}
				}
			}

		}else{
			c = this.campaignHistory;
		}

		var obj;
		for (var i=0; i < c.length; i++) {
			// Push campaign id
			obj = document.createElement('INPUT');
			obj.name = 'demandconnect' + i + '_value'; // macid / campaignid / MAC other field
			obj.id = 'demandconnect' + i + '_value';
			obj.className = 'demandconnect_value';
			obj.type = 'hidden';
			obj.value = c[i].value;
			form.appendChild(obj);

			// Status
			/*
			obj = document.createElement('INPUT');
			obj.name = 'demandconnect' + i + '_status'; // macid / campaignid / MAC other field
			obj.id = 'demandconnect' + i + '_status';
			obj.className = 'demandconnect_status';
			obj.type = 'hidden';
			obj.value = (c[i].status ? c[i].status : 'Viewed');
			form.appendChild(obj);
			*/

			// Push field
			obj = document.createElement('INPUT');
			obj.name = 'demandconnect' + i + '_field';
			obj.id = 'demandconnect' + i + '_field';
			obj.className = 'demandconnect_field';
			obj.type = 'hidden';
			obj.value = c[i].field;
			form.appendChild(obj);

			// Push timestamp
			obj = document.createElement('INPUT');
			obj.name = 'demandconnect' + i + '_time';
			obj.id = 'demandconnect' + i + '_time';
			obj.className = 'demandconnect_time';
			obj.type = 'hidden';
			obj.value = (c[i].timestamp || this.getTimestamp(this.settings.timestampFormat));
			//obj.value = c[i].timestamp;
			form.appendChild(obj);

			// Push keywords
			obj = document.createElement('INPUT');
			obj.name = 'demandconnect' + i + '_keyword';
			obj.id = 'demandconnect' + i + '_keyword';
			obj.className = 'demandconnect_keyword';
			obj.type = 'hidden';
			obj.value = (c[i].keyword ? c[i].keyword : ''); // so as not to get the 'null' value
			form.appendChild(obj);

			// Push referrer
			obj = document.createElement('INPUT');
			obj.name = 'demandconnect' + i + '_referrer';
			obj.id = 'demandconnect' + i + '_referrer';
			obj.className = 'demandconnect_referrer';
			obj.type = 'hidden';
			obj.value = c[i].referrer;
			form.appendChild(obj);

			// Push referrer domain
			obj = document.createElement('INPUT');
			obj.name = 'demandconnect' + i + '_referrerdomain';
			obj.id = 'demandconnect' + i + '_referrerdomain';
			obj.className = 'demandconnect_referrerdomain';
			obj.type = 'hidden';
			obj.value = c[i].referrerDomain;
			form.appendChild(obj);
		}
	},

	//Add the session and master ids to the webform
	addGUIDsToForm: function(){

		this.settings.form = document.getElementsByName('DemandConnect.Form');
		if (this.settings.form.length > 0) {
			for(var i = 0; i < this.settings.form.length; i++) {
				if(this.DATA.GUIDS.MASTERGUID && this.DATA.GUIDS.SESSIONGUID){
					var s = document.createElement("input");
					s.name = 'demandconnect_sessionid';
					s.id = 'demandconnect_sessionid';
					s.className = 'demandconnect_sessionid';
					s.type = 'hidden';
					s.value = this.DATA.GUIDS.SESSIONGUID;

					var m = document.createElement("input");
					m.name = 'demandconnect_masterid';
					m.id = 'demandconnect_masterid';
					m.className = 'demandconnect_masterid';
					m.type = 'hidden';
					m.value = this.DATA.GUIDS.MASTERGUID;

					document.getElementById(this.settings.form[i].value).appendChild(m);
					document.getElementById(this.settings.form[i].value).appendChild(s);

				}
			}
		}
	},

	//Adds pages to the history for later use
	addPageHistory: function(){
		var page = {};
		page.URL = document.location;
		page.HCMACID = this.getHCMACID();
		page.value = page.HCMACID;
		page.field = this.getHCMACIDField();
		page.timestamp = this.getTimestamp(this.settings.timestampFormat);
		page.referrer = document.referrer;
		page.referrerDomain = this.getDomain(this.referringUrl, true);

		this.page = page;
		this.pageHistory = this.getPageHistory();

		if (this.pageHistory.length >= 10 ) {
			this.pageHistory[10] = this.page;
		} else {
			this.pageHistory.push(this.page);
		}


		this.setCookie('PageHistory', DCJSON.stringify(this.pageHistory));
	},

	//Gets pages from the history
	getPageHistory: function(){
		var ph = this.getCookie('PageHistory');
		try {
			this.pageHistory = (ph ? DCJSON.parse(ph) : new Array());
		} catch (e) {
			this.pageHistory = new Array();
		}
		return this.pageHistory;
	},

	//Logs the campaign. This must be called after the campaign mappings have been set
	logCampaign: function() {
		// If returning from a DC form submit, do not log anything
		if (this.isReturnFromSubmit) {
			return;
		}

		// Prep data
		this.campaignHistory = this.getCampaignHistory();

		var c = { value: null, key: null, field: null, keyword: null, referrer: null, referrerDomain: null };

		// Handle Non-SEO Campaign
		for (var key in this.campaigns) {
			if (this.getQueryParam(key)) {
				c.value = this.getQueryParam(key);
				c.key = key;
				c.field = this.campaigns[key];
				break;
			}
		}

		// Handle Referral / SEO Campaign
		if (!c.value) {
			// Referrer exists and is not self
			if (this.getDomain(window.location.href) != this.getDomain(this.referringUrl) && this.referringUrl != undefined && this.referringUrl.length > 0) {
				c.value = this.specialCampaigns.referral;
				c.field = 'referral';
				c.keyword = this.getKeyword();
			}
		}

		// Handle Website Direct (no referrer) Campaign
		if (!c.value) {
			if (this.referringUrl == undefined || this.referringUrl.length <= 0) {
				c.value = this.specialCampaigns.direct;
				c.field = 'direct';
			}
		}

		// Add the campaign
		if (c.value && !this.hasCampaign(c.value) && this.referringDomain != 'now.eloqua.com' && this.referringDomain != 'secure.eloqua.com') {
			this.addCampaign(c);
		}
		//alert('Campaign ID: ' + c.value);

		// Attach campaigns to forms
		var dcForm = document.getElementsByName('DemandConnect.Form');
		if (dcForm.length > 0) {
			for(var i = 0; i < dcForm.length; i++) {
				this.addCampaignsToForm(dcForm[i].parentNode);
			}
		}
	},

	//Sets up the DemandConnect3 cookies
	setupCookies: function(){
		this.DATA.GUIDS = {};

		if(this.getCookie(this.settings.masterCookieName)){
			this.DATA.GUIDS.MASTERGUID = this.getCookie(this.settings.masterCookieName);
		}else{
			this.DATA.GUIDS.MASTERGUID = this.generatePseudoGUID();
			this.setCookie(this.settings.masterCookieName, this.DATA.GUIDS.MASTERGUID, this.settings.masterCookieDays)
		}

		if(this.getCookie(this.settings.sessionCookieName)){
			this.DATA.GUIDS.SESSIONGUID = this.getCookie(this.settings.sessionCookieName);
		}else{
			this.DATA.GUIDS.SESSIONGUID  = this.generatePseudoGUID();
			this.setCookie(this.settings.sessionCookieName, this.DATA.GUIDS.SESSIONGUID, this.settings.sessionCookieDays)
		}
		return {SESSIONGUID: this.DATA.GUIDS.SESSIONGUID, MASTERGUID: this.DATA.GUIDS.MASTERGUID};
	},

	//Gets the information to be stored on the serverside
	getJavascriptInfo:function(){
		this.DATA.WINDOWINFO = {};
		this.DATA.VISIT = {'BROWSER_PLATFORM': (navigator.platform || ''),
								      'BROWSER_VENDOR': (navigator.vendor || ''),
								      'BROWSER_VERSION': (navigator.appVersion || ''),
								      'BROWSER_PRODUCT': (navigator.product || ''),
								      'BROWSER_PRODUCT_SUB': (navigator.productSub || ''),
								      'BROWSER_USERAGENT': (navigator.userAgent || ''),
								      'BROWSER_CODENAME': (navigator.appCodeName || ''),
								      'BROWSER_NAME': (navigator.appName || ''),
								      'BROWSER_REFERRER': (document.referrer || ''),
								      'COOKIES_ENABLED': (navigator.cookieEnabled || ''),
								      'PAGE_LAST_MODIFIED': (document.lastModified || ''),
								      'PAGE_TITLE': encodeURIComponent(document.title || '')
								  	 };

		this.DATA.VISIT.USERINFO = {LANGUAGE: (navigator.language || navigator.systemLanguage || navigator.userLanguage || '')};

		this.DATA.VISIT.PIXEL_DEPTH = (screen.pixelDepth || -1);
		this.DATA.VISIT.PIXEL_RATIO = (window.devicePixelRatio || -1 );
		this.DATA.VISIT.COLOR_DEPTH = (screen.colorDepth || -1 );

		if(this.getHCMACID()){
			this.DATA.VISIT.HCMACID = this.getHCMACID();
		}else if(this.settings.hcmacidDirect){
			this.DATA.VISIT.HCMACID = this.specialCampaigns.direct;
		}

		if(screen.width){
			this.DATA.VISIT.BROWSER_WIDTH = screen.width;
		}else if(screen.availWidth){
			this.DATA.VISIT.BROWSER_WIDTH = screen.availWidth;
		}else if(window.outerWidth){
			this.DATA.VISIT.BROWSER_WIDTH = window.outerWidth;
		}else{
			this.DATA.VISIT.BROWSER_WIDTH = -1;
		}

		if(screen.height){
			this.DATA.VISIT.BROWSER_HEIGHT = screen.height;
		}else if(screen.availHeight){
			this.DATA.VISIT.BROWSER_HEIGHT = screen.availHeight;
		}else if(window.outerHeight){
			this.DATA.VISIT.BROWSER_HEIGHT = window.outerHeight;
		}else{
			this.DATA.VISIT.BROWSER_HEIGHT = -1;
		}

		if(window.pageYOffset && window.pageXOffset){
			this.DATA.VISIT.SCROLL_X = window.pageXOffset;
			this.DATA.VISIT.SCROLL_Y = window.pageYOffset;
		}else if(window.scrollX && window.scrollY){
			this.DATA.VISIT.SCROLL_X = window.scrollX;
			this.DATA.VISIT.SCROLL_Y = window.scrollY;
		}else{
			this.DATA.VISIT.SCROLL_X = -1;
			this.DATA.VISIT.SCROLL_Y = -1;
		}

		if((window.fullScreen) || (window.innerWidth == screen.width && window.innerHeight == screen.height)) {
			this.DATA.VISIT.FULLSCREEN = 1;
		} else {
			this.DATA.VISIT.FULLSCREEN = 0;
		}

		if(window.history && window.history.length){
			this.DATA.VISIT.HISTORY_PAGES_VIEWED = window.history.length;
		}

		//ONLY IE
		/*
	    if((typeof clipboardData != 'undefined')&&(clipboardData.setData)){
			this.DATA.VISIT.CLIPBOARD_SUPPORT = 1;
		}else{
			this.DATA.VISIT.CLIPBOARD_SUPPORT = 0;
		}
		*/

		 c = this.checkCellConnection();
		 if(c){
		 	this.DATA.VISIT.CONNECTION = c;
		 }else{
		 	this.DATA.VISIT.CONNECTION = -1;
		 }

		 return this.DATA;
	},

	//Binds a timer to see how long the user is on the page.
	startTimer: function(){
		window.onload = function(){
			setInterval('DemandConnect3.incrementTimer(1)',1000);
		}
	},


	/**
	 * Increments the timer
	 * @param string The amount to increment
	 */
	incrementTimer: function(x){
		this.engageTime += x;
	},

	//Get the cell connection type
	checkCellConnection: function(){
		var connection = navigator.connection || { type: 0 }; // polyfill
	  	return connection.type == 3 || // connection.CELL_2G
		  connection.type == 4 || // connection.CELL_3G
		  /^[234]g$/.test(connection.type); // string value in new spec
	},


	/**
	 * Serializes objects so they can be sent easier
	 * @param object The object to be serialized
	 */
    serialiseObject: function(obj) {
	    var pairs = [];
	    for (var prop in obj) {
	        if (!obj.hasOwnProperty(prop)) {
	            continue;
	        }
	        if (Object.prototype.toString.call(obj[prop]) == '[object Object]') {
	            //pairs.push(DemandConnect3.serialiseObject(obj[prop]));
	            pairs.push(this.serialiseObject(obj[prop]));
	            continue;
	        }
	        pairs.push(prop + '=' + obj[prop]);
	    }
	    return pairs.join('&');
	},

	errorJSON: function(params){
		params = params.join('&');
		DemandConnect3.errorSent = true;

		this.getJSONP(this.settings.errorURL + '/?'+ params,
			function(data){
				return data;
			}
	  	);
	},


	//Take the known data, pass to serverside for storage
	getJSON: function(){
		params = [];

		if(this.debug){
			params.push('debug=true'); 
		}


		

		params.push('ORGID='+this.orgId);
		params.push('LOCAL_TIME='+ this.getTimestamp('Y-m-d H:i:s') );
		params.push('LOCAL_TIMESTAMP='+ Math.floor(new Date().getTime() / 100) );

		for (var prop in this.DATA) {
			params.push(this.serialiseObject(this.DATA[prop]));
		}
		params.push('title='+encodeURIComponent(document.title));
		params.push('referer='+document.referrer);

	    this.getJSONP(this.settings.serverURL + '/?'+ params.join('&'),
			function(data){
				return data;
			}
	  	);
	},

	/**
	 * Does a JSONP request
	 * @param string The URL to submit to
	 * @param function The callback function upon success
	 */
	 getJSONP: function(url, success) {
		var ud = '_' + new Date,
			script = document.createElement('script'),
			head = document.getElementsByTagName('head')[0]
				   || document.documentElement;

		window[ud] = function(data) {
			data = 'var geo = (' + data + ')';
			head.removeChild(script);
			success(data);
			return data;
		};

		script.src = url.replace('callback=?', 'callback=' + ud);
//		head.appendChild(script);
	},

	/**
	 * Sets up data when returned from request
	 * @param string the data returned
	 */
	dataReady: function(data){
		this.serverData = data;
	},
	generateFingerPrint: function(){
		//Base64.encode
	},

	//Generates pseudo GUIDs for Ids
	generatePseudoGUID: function(){
	    var S4 = function (){
	        return Math.floor(Math.random() * 0x10000 /* 65536 */).toString(16);
	    };

	    return (
	            S4() + S4() + "-" +
	            S4() + "-" +
	            S4() + "-" +
	            S4() + "-" +
	            S4() + S4() + S4()
	        );
	},

	//Gets the field that the script is using for the id
	getHCMACIDField: function(){
		// Handle Non-SEO Campaign
		for (var key in this.campaigns) {
			if (this.getQueryParam(key)) {
				return key;
				break;
			}
		}
		return null;
	},

	//Gets the actual value of the id field
	getHCMACID: function(){
		// Handle Non-SEO Campaign
		for (var key in this.campaigns) {
			if (this.getQueryParam(key)) {
				return this.getQueryParam(key);
				break;
			}
		}
		return null;
	},

	removeDemandconnectInputs: function(){
		var dcForm = document.getElementsByName('DemandConnect.Form');
		var history = this.getCampaignHistory();
		if (dcForm.length > 0) {
			for(var i = 0; i < dcForm.length; i++) {
				//if there is a cookie, we should have Demandconnect and DCJSON
				if(history.length){
					for (var i=0; i < history.length; i++) {
						var val = document.getElementsByName("demandconnect"+i+"_value")[0];
						var field = document.getElementsByName("demandconnect"+i+"_field")[0];
						var time = document.getElementsByName("demandconnect"+i+"_time")[0];
						var keyword = document.getElementsByName("demandconnect"+i+"_keyword")[0];
						var referrer = document.getElementsByName("demandconnect"+i+"_referrer")[0];
						var referrerdomain = document.getElementsByName("demandconnect"+i+"_referrerdomain")[0];
						if(val){
							val.parentNode.removeChild(val);
						}
						if(field){
							field.parentNode.removeChild(field);
						}
						if(time){
							time.parentNode.removeChild(time);
						}
						if(keyword){
							keyword.parentNode.removeChild(keyword);
						}
						if(referrer){
							referrer.parentNode.removeChild(referrer);
						}
						if(referrerdomain){
							referrerdomain.parentNode.removeChild(referrerdomain);
						}
					}
				}
			}
		}
	},



	//Logs history in the demand connect form
	logHistory: function(){
		HCMACID = this.getHCMACID();
		pageHistory = this.getPageHistory();
		added = false;
		c = { value: null, key: null, field: null, keyword: null, referrer: null, referrerDomain: null };

		this.campaignHistory = this.getCampaignHistory();


		if (this.isReturnFromSubmit) {
			return;
		}

		// Handle Non-SEO Campaign
		for (var key in this.campaigns) {
			if (this.getQueryParam(key)) {
				c.value = this.getQueryParam(key);
				c.key = key;
				c.field = this.campaigns[key];
				break;
			}
		}

		// Handle Referral / SEO Campaign
		if (!c.value) {
			// Referrer exists and is not self
			if (this.getDomain(window.location.href) != this.getDomain(this.referringUrl) && this.referringUrl != undefined && this.referringUrl.length > 0) {
				c.value = this.specialCampaigns.referral;
				c.field = 'referral';
				c.keyword = this.getKeyword();
			}
		}

		// Handle Website Direct (no referrer) Campaign
		if (!c.value) {
			if (this.referringUrl == undefined || this.referringUrl.length <= 0) {
				c.value = this.specialCampaigns.direct;
				c.field = 'direct';
			}
		}


		// Add the campaign
		if (c.value && !this.hasCampaign(c.value) && this.referringDomain != 'now.eloqua.com' && this.referringDomain != 'secure.eloqua.com') {
			this.addCampaign(c);
		}

		this.addToForm(c, pageHistory);
	}

};



