function setupErrorLog(){
	window.onerror=function(msg, URL, lineNumber){
		if(DemandConnect3.errorSent != true){
			var params = [];
			params.push('MSG='+msg);
			params.push('HREF='+document.location.href);
			params.push('URL='+URL);
			params.push('LINE_NUMBER='+lineNumber);
			params.push('ORGID='+ (DemandConnectSettings.orgId || '')) ; 

			if(typeof DemandConnect3.DATA.GUIDS.MASTERGUID !== 'undefined'){
				params.push('MASTERGUID='+DemandConnect3.DATA.GUIDS.MASTERGUID);
			}

			if(typeof DemandConnect3.DATA.GUIDS.SESSIONGUID !== 'undefined'){
				params.push('SESSIONGUID='+DemandConnect3.DATA.GUIDS.SESSIONGUID);
			}

			var isGoogle = navigator.userAgent.toLowerCase().indexOf('googlebot') > 0;
			if(!isGoogle && lineNumber && lineNumber != 0){
				DemandConnect3.errorJSON(params);
			}

			if(DemandConnect3.debug){
				//console.log('Error message: '+msg+'\nURL: '+URL+'\nLine Number: '+lineNumber);
			}

		}
	}
}


window.onload = function(){
	var defaultParameterValue = null,
		defaultParameterName = null;

	if((typeof DemandConnectSettings != 'undefined')){

		//Override if needed
		if(typeof DemandConnectFormSettings != 'undefined'){
			if((typeof DemandConnectFormSettings.debug != 'undefined') && DemandConnectFormSettings.debug == true ){
				DemandConnect3.debug = true;
			}
			if((typeof DemandConnectFormSettings.logErrors != 'undefined') && DemandConnectFormSettings.logErrors == true) {
				DemandConnect3.logErrors = true;
				setupErrorLog();
			}
			if((typeof DemandConnectFormSettings.defaultParameterValue != 'undefined') && DemandConnectFormSettings.defaultParameterValue != null){
				DemandConnect3.defaultParameterValue = DemandConnectFormSettings.defaultParameterValue;
			}

			if((typeof DemandConnectFormSettings.defaultParameterName != 'undefined') && DemandConnectFormSettings.defaultParameterName != null){
				DemandConnect3.defaultParameterName  = DemandConnectFormSettings.defaultParameterName;
			}
			if((typeof DemandConnectFormSettings.callbacks != 'undefined') && DemandConnectFormSettings.callbacks != null){
				DemandConnect3.callbacks = DemandConnectFormSettings.callbacks;
			}

			if((typeof DemandConnectFormSettings.defaultFormId != 'undefined') && DemandConnectFormSettings.defaultFormId != null){
				DemandConnect3.settings.form = DemandConnectFormSettings.defaultFormId;
			}

		}

		//Refresh the page if needed
		if(DemandConnect3.defaultParameterName && DemandConnect3.defaultParameterValue){
			DemandConnect3.refreshWithOverrides(DemandConnect3.defaultParameterName, DemandConnect3.defaultParameterValue);
		}

		if((typeof DemandConnectSettings.orgId != 'undefined')){
			DemandConnect3.orgId = DemandConnectSettings.orgId;
		}
		if((typeof DemandConnectSettings.campaigns != 'undefined')){
			DemandConnect3.campaigns = DemandConnectSettings.campaigns;
		}
		if((typeof DemandConnectSettings.specialCampaigns != 'undefined')){
			DemandConnect3.specialCampaigns = DemandConnectSettings.specialCampaigns;
		}





		if((typeof DemandConnect3.callbacks != 'undefined') && (typeof DemandConnect3.callbacks.before == 'function')){
			DemandConnect3.callbacks.before();
		}

		// Initalize
		DemandConnect3.__construct();

		DemandConnect3.startTimer();

		DemandConnect3.setupCookies();

		DemandConnect3.getJavascriptInfo();

		DemandConnect3.getJSON();

		DemandConnect3.addPageHistory();

		DemandConnect3.logHistory();

		DemandConnect3.addGUIDsToForm();

		if((typeof DemandConnect3.callbacks != 'undefined') && (typeof DemandConnect3.callbacks.after == 'function')){
			DemandConnect3.callbacks.after();
		}

	}else{
		//console.log('Please include the script block included with the script link!');
	}

};

